package com.securelib.crypto.redirect

import kotlinx.coroutines.*
import java.security.MessageDigest
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Secure redirect service with HMAC-verified redirect tokens.
 * Tokens encode the target URL and are signed to prevent tampering.
 */
object RedirectConfig {
    val ALLOWED_SCHEMES = setOf("https")
    val ALLOWED_HOSTS = setOf("app.example.com", "cdn.example.com", "auth.example.com")
    const val HMAC_ALGORITHM = "HmacSHA256"
    // Require the HMAC key to be provided via the environment. Fail closed if it
    // is missing or too weak instead of falling back to a predictable hardcoded key.
    val SECRET_KEY: ByteArray = run {
        val configured = System.getenv("REDIRECT_HMAC_KEY")
            ?: throw IllegalStateException("REDIRECT_HMAC_KEY environment variable is not set")
        val bytes = configured.toByteArray()
        require(bytes.size >= 32) { "REDIRECT_HMAC_KEY must be at least 32 bytes" }
        bytes
    }
}

data class RedirectToken(
    val targetUrl: String,
    val nonce: String,
    val timestamp: Long,
    val signature: String
)

class HmacSigner(private val key: ByteArray) {
    fun sign(data: String): String {
        val mac = Mac.getInstance(RedirectConfig.HMAC_ALGORITHM)
        mac.init(SecretKeySpec(key, RedirectConfig.HMAC_ALGORITHM))
        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(data.toByteArray()))
    }

    fun verify(data: String, signature: String): Boolean {
        val expected = sign(data)
        return MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())
    }
}

class UrlValidator {
    private val validationCache = ConcurrentHashMap<String, Boolean>()

    fun extractScheme(url: String): String {
        val colonIdx = url.indexOf(':')
        if (colonIdx <= 0) return ""
        return url.substring(0, colonIdx).lowercase()
    }

    fun extractHost(url: String): String {
        val withoutScheme = url.substringAfter("://")
        val hostEnd = withoutScheme.indexOfFirst { it == '/' || it == '?' || it == '#' || it == ':' }
        return if (hostEnd == -1) withoutScheme.lowercase() else withoutScheme.substring(0, hostEnd).lowercase()
    }

    suspend fun validateUrl(url: String): Boolean {
        validationCache[url]?.let { return it }

        val result = coroutineScope {
            val schemeCheck = async {
                delay(1) // simulate async scheme resolution
                val scheme = extractScheme(url)
                scheme in RedirectConfig.ALLOWED_SCHEMES
            }

            val hostCheck = async {
                delay(1) // simulate async DNS/host verification
                val host = extractHost(url)
                host in RedirectConfig.ALLOWED_HOSTS
            }

            schemeCheck.await() && hostCheck.await()
        }

        validationCache[url] = result
        return result
    }
}

class RedirectService(
    private val signer: HmacSigner = HmacSigner(RedirectConfig.SECRET_KEY),
    private val validator: UrlValidator = UrlValidator()
) {
    private val usedNonces = ConcurrentHashMap<String, Long>()

    fun createToken(targetUrl: String, nonce: String): RedirectToken {
        val timestamp = System.currentTimeMillis()
        val payload = "$targetUrl|$nonce|$timestamp"
        val signature = signer.sign(payload)
        return RedirectToken(targetUrl, nonce, timestamp, signature)
    }

    private fun isNonceUsed(nonce: String): Boolean {
        val now = System.currentTimeMillis()
        usedNonces.entries.removeIf { now - it.value > 300_000 }
        return usedNonces.putIfAbsent(nonce, now) != null
    }

    private fun isTokenExpired(timestamp: Long): Boolean {
        return System.currentTimeMillis() - timestamp > 300_000
    }

    /**
     * Resolves a redirect token to a validated URL.
     * Performs HMAC verification, nonce check, expiry check, and URL validation.
     */
    suspend fun resolveRedirect(token: RedirectToken): Result<String> {
        // Step 1: Verify HMAC signature
        val payload = "${token.targetUrl}|${token.nonce}|${token.timestamp}"
        if (!signer.verify(payload, token.signature)) {
            return Result.failure(SecurityException("Invalid token signature"))
        }

        // Step 2: Check token expiry
        if (isTokenExpired(token.timestamp)) {
            return Result.failure(SecurityException("Token expired"))
        }

        // Step 3: Check nonce reuse
        if (isNonceUsed(token.nonce)) {
            return Result.failure(SecurityException("Nonce already used"))
        }

        // Step 4: Validate the target URL
        val urlToValidate = normalizeUrl(token.targetUrl)
        if (!validator.validateUrl(urlToValidate)) {
            return Result.failure(SecurityException("URL not in allowlist"))
        }

        // Return the VALIDATED (normalized) url
        return Result.success(urlToValidate)
    }

    /**
     * Normalizes URL for validation purposes.
     * Handles encoded characters and case normalization.
     */
    private fun normalizeUrl(url: String): String {
        // Decode percent-encoded characters for validation
        var normalized = url
        val regex = Regex("%([0-9A-Fa-f]{2})")
        normalized = regex.replace(normalized) { match ->
            val charCode = match.groupValues[1].toInt(16)
            // Only decode unreserved characters per RFC 3986
            if (charCode in 0x41..0x5A || charCode in 0x61..0x7A ||
                charCode in 0x30..0x39 || charCode == 0x2D ||
                charCode == 0x2E || charCode == 0x5F || charCode == 0x7E) {
                charCode.toChar().toString()
            } else {
                match.value
            }
        }
        return normalized
    }
}

// HTTP handler simulation
class RedirectHandler(private val service: RedirectService = RedirectService()) {
    suspend fun handleRedirect(encodedToken: String): Pair<Int, Map<String, String>> {
        return try {
            val parts = String(Base64.getUrlDecoder().decode(encodedToken)).split("|")
            if (parts.size != 4) return Pair(400, mapOf("error" to "malformed token"))

            val token = RedirectToken(
                targetUrl = parts[0],
                nonce = parts[1],
                timestamp = parts[2].toLong(),
                signature = parts[3]
            )

            val result = service.resolveRedirect(token)
            result.fold(
                onSuccess = { url -> Pair(302, mapOf("Location" to url)) },
                onFailure = { e -> Pair(403, mapOf("error" to (e.message ?: "forbidden"))) }
            )
        } catch (e: Exception) {
            Pair(400, mapOf("error" to "invalid request"))
        }
    }
}
